CREATE TABLE IF NOT EXISTS agent_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),channel_id text NOT NULL REFERENCES channels(id),version integer NOT NULL,model text NOT NULL,persona text NOT NULL,enabled boolean NOT NULL DEFAULT false,state text NOT NULL CHECK(state IN ('DRAFT','PUBLISHED','ARCHIVED')),created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,UNIQUE(channel_id,version)); CREATE UNIQUE INDEX IF NOT EXISTS agent_one_draft ON agent_versions(channel_id) WHERE state='DRAFT'; CREATE UNIQUE INDEX IF NOT EXISTS agent_one_published ON agent_versions(channel_id) WHERE state='PUBLISHED';